import { Form, Input, Button, Card, Typography, message } from "antd";
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

const { Title } = Typography;

const LoginPage = () => {
    const [loading, setLoading] = useState(false);
    const [formError, setFormError] = useState("");
    const navigate = useNavigate();

    const onFinish = async (values) => {
        setLoading(true);
        setFormError("");

        try {
            const response = await axios.post("https://development-iyl1.onrender.com/validate",
                values,  // Aquí envías directamente el objeto de formulario
                {
                    headers: {
                        "Content-Type": "application/json",  // Especificamos el tipo de contenido
                    }
                }
            );

            if (response.data.statusCode === 200) {
                message.success("Inicio de sesión exitoso");
                localStorage.setItem("token", response.data.data.token); // Almacenar el token recibido en el localStorage
                navigate("/dashboard"); // Redirigir al dashboard
            } else {
                setFormError("Credenciales incorrectas");
            }
        } catch (error) {
            setFormError("Error en la autenticación");
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        document.body.style.margin = "0";
        document.documentElement.style.height = "100%";
        document.body.style.height = "100%";
    }, []);

    return (
        <div style={styles.container}>
            <Card style={styles.card} bordered={false}>
                <Title level={2} style={{ textAlign: "center", color: "#333" }}>
                    Iniciar Sesión
                </Title>

                <Form layout="vertical" onFinish={onFinish}>

                    <Form.Item
                        label="Usuario"
                        name="username"
                        rules={[{ required: true, message: "Por favor, ingrese su usuario" }]}
                        validateStatus={formError ? "error" : ""}
                        help={formError && formError}
                        style={{ width: "60%" }}
                    >
                        <Input placeholder="Usuario" />
                    </Form.Item>

                    <Form.Item
                        label="Contraseña"
                        name="password"
                        rules={[
                            { required: true, message: "Ingrese su contraseña" },
                            { min: 6, message: "Debe tener al menos 6 caracteres" },
                        ]}
                        validateStatus={formError ? "error" : ""}
                        help={formError && formError}
                        style={{ width: "100%" }} 
                    >
                        <Input.Password placeholder="Contraseña" />
                    </Form.Item>

                    <Form.Item>
                        <Button
                            type="primary"
                            htmlType="submit"
                            block
                            loading={loading}
                            style={styles.button}
                        >
                            Iniciar Sesión
                        </Button>
                    </Form.Item>
                </Form>
            </Card>
        </div>
    );
};

const styles = {
    container: {
        height: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "linear-gradient(135deg, #667eea, #764ba2)",
    },
    card: {
        width: 380,
        padding: 20,
        borderRadius: 10,
        boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.3)",
        background: "#fff",
    },
    button: {
        backgroundColor: "#1890ff",
        borderColor: "#1890ff",
        fontSize: "16px",
    },
    errorMessage: {
        color: "#f5222d",
        marginBottom: "10px",
        fontSize: "14px",
        textAlign: "center",
    },
    center: {
        textAlign: "center",
        marginTop: "10px",
    },
};

export default LoginPage;
